def separate_paren_groups(paren_string: str) -> List[str]:
    result = []
    current_group = []
    depth = 0

    for char in paren_string.replace(" ", ""):
        if char == '(':
            depth += 1
            current_group.append(char)
        elif char == ')':
            depth -= 1
            current_group.append(char)
            if depth == 0:
                result.append(''.join(current_group))
                current_group = []

    return result

def below_zero(operations: List[int]) -> bool:
    balance = 0
    for operation in operations:
        balance += operation
        if balance < 0:
            return True
    return False

def mean_absolute_deviation(numbers: List[float]) -> float:
    if not numbers:
        return 0.0

    mean = sum(numbers) / len(numbers)
    total_sum = sum(abs(x - mean) for x in numbers)

    return total_sum / len(numbers)

def find_topmost_carpet(n, carpets, point) -> int:
    x, y = point
    topmost_carpet = -1

    for i in range(n):
        a, b, g, k = carpets[i]

        if a <= x <= a + g and b <= y <= b + k:
            topmost_carpet = i + 1

    return topmost_carpet

def max_value_on_paths(N: int, grid_values: List[Tuple[int, int, int]]) -> int:
    # Initialize the grid with zeros
    grid = [[0] * N for _ in range(N)]

    # Fill the grid with the given values
    for x, y, val in grid_values:
        if x == 0 and y == 0 and val == 0:
            continue
        grid[x-1][y-1] = val

    # Initialize the DP table
    dp = [[[-float('inf')] * 2 for _ in range(N)] for _ in range(N)]
    dp[0][0][0] = grid[0][0]

    # Fill the DP table
    for i in range(N):
        for j in range(N):
            if i == 0 and j == 0:
                continue
            if i > 0:
                dp[i][j][0] = max(dp[i][j][0], dp[i-1][j][0] + grid[i][j])
            if j > 0:
                dp[i][j][1] = max(dp[i][j][1], dp[i][j-1][1] + grid[i][j])

    # Find the maximum sum of values collected on the two paths
    max_sum = 0
    for i in range(N):
        for j in range(N):
            max_sum = max(max_sum, dp[i][j][0] + dp[i][j][1] - grid[i][j])

    return max_sum

