def max_product(num_str: str, N: int, K: int) -> int:
    def recursive_max_product(index: int, remaining_multiplications: int, current_product: int) -> int:
        if remaining_multiplications == 0:
            return current_product
        if index == N:
            return current_product

        max_product = 0
        for next_index in range(index, N):
            product = current_product * int(num_str[index:next_index + 1])
            max_product = max(max_product, recursive_max_product(next_index + 1, remaining_multiplications - 1, product))

        return max_product

    if K == 0:
        return int(num_str)

    return recursive_max_product(0, K, 1)

def optimize_seating(M: int, N: int, K: int, L: int, D: int, chatting_pairs: list) -> (str, str):
    # Count the number of chatting pairs that can be separated by adding an aisle in each possible position
    row_effects = [0] * (M + 1)
    col_effects = [0] * (N + 1)

    for a, b, c, d in chatting_pairs:
        if a == c:  # Vertical chatting
            row_effects[a] += 1
            row_effects[c + 1] -= 1
        if b == d:  # Horizontal chatting
            col_effects[b] += 1
            col_effects[d + 1] -= 1

    # Calculate the cumulative effects for rows and columns
    for i in range(1, M + 1):
        row_effects[i] += row_effects[i - 1]

    for j in range(1, N + 1):
        col_effects[j] += col_effects[j - 1]

    # Select the most effective positions for aisles
    top_row_aisles = []
    for i in range(1, M + 1):
        if row_effects[i] > 0:
            top_row_aisles.append(str(i))

    left_col_aisles = []
    for j in range(1, N + 1):
        if col_effects[j] > 0:
            left_col_aisles.append(str(j))

    # Ensure we only add the specified number of aisles
    top_row_aisles = top_row_aisles[:K]
    left_col_aisles = left_col_aisles[:L]

    return ' '.join(top_row_aisles), ' '.join(left_col_aisles)

