def max_energy(beads):
    n = len(beads)
    dp = [[0] * n for _ in range(n)]

    for length in range(2, n + 1):
        for i in range(n):
            j = (i + length - 1) % n
            dp[i][j] = max(dp[i][k] + dp[k + 1][j] + beads[i] * beads[k] * beads[j] for k in range(i, j))

    return dp[0][(n - 1) % n]

def polynomial_to_string(n: int, coeffs: List[int]) -> str:
    terms = []
    for i in range(n, -1, -1):
        coeff = coeffs[n - i]
        if coeff != 0:
            if coeff == 1:
                coeff_str = '' if i == 0 else 'x'
            elif coeff == -1:
                coeff_str = '-' if i == 0 else '-x'
            else:
                coeff_str = str(abs(coeff)) + ('' if i == 0 else 'x')

            if i > 1:
                coeff_str += f'^{i}'

            terms.append(coeff_str)

    return ''.join(terms)

def decode(encoded: str, original: str, message: str) -> str:
    if len(encoded) != len(original):
        return "Failed"

    mapping = {}
    for e, o in zip(encoded, original):
        if e in mapping and mapping[e] != o:
            return "Failed"
        mapping[e] = o

    if len(mapping) < 26:
        return "Failed"

    decoded = ''.join(mapping.get(char, char) for char in message)
    return decoded

