def count_partitions(n: int, k: int, x: int) -> int:
    """
    Counts the number of ways to partition an integer n into k parts,
    where each part is at least x and order of parts does not matter.

    Parameters:
    n (int): The integer to be partitioned.
    k (int): The number of parts to divide n into.
    x (int): The minimum value for each part.

    Returns:
    int: The number of distinct partitioning ways.
    """
    # Helper function to solve the partition problem using recursion
    def helper(n, k, x, min_val):
        if k == 1:
            return 1 if n >= min_val else 0
        if n < k * min_val:
            return 0
        return helper(n - min_val, k - 1, x, min_val) + helper(n, k, x, min_val + 1)

    return helper(n, k, x, x)

def is_prime(num: int) -> bool:
    """
    Determine whether a given integer is a prime number.

    Args:
    num (int): The integer to check for primality.

    Returns:
    bool: True if `num` is a prime number, False otherwise.
    """
    if num <= 1:
        return False
    if num <= 3:
        return True
    if num % 2 == 0 or num % 3 == 0:
        return False
    i = 5
    while i * i <= num:
        if num % i == 0 or num % (i + 2) == 0:
            return False
        i += 6
    return True

def generate_numbers(n, rules) -> int:
    # Convert the number to a string to easily manipulate digits
    num_str = str(n)
    # Create a set to store unique numbers
    unique_numbers = set()
    # Initialize a queue for BFS
    queue = deque([num_str])

    while queue:
        current_num_str = queue.popleft()
        if current_num_str not in unique_numbers:
            unique_numbers.add(current_num_str)
            # Try applying each transformation rule to each digit
            for i in range(len(current_num_str)):
               _digit = int(current_num_str[i])
                for x, y in rules:
                    if _digit == x:
                        new_num_str = current_num_str[:i] + str(y) + current_num_str[i+1:]
                        queue.append(new_num_str)

    return len(unique_numbers)

