def jinjin_savings_plan(budgets: List[int]) -> int:
    total_savings = 0
    pocket_money = 300

    for month in range(12):
        remaining_money = pocket_money - budgets[month]

        if remaining_money - 100 < 0:
            return -(month + 1)

        savings = 100 * (remaining_money // 100)
        total_savings += savings

    return total_savings * 1.2

def minimum_students_to_leave(heights):
    n = len(heights)
    if n == 1:
        return 0

    def increasing_subsequence(data):
        dp = [1] * n
        for i in range(1, n):
            for j in range(i):
                if data[i] > data[j]:
                    dp[i] = max(dp[i], dp[j] + 1)
        return dp

    inc = increasing_subsequence(heights)
    dec = increasing_subsequence(heights[::-1])[::-1]

    max_choir_length = 0
    for i in range(n):
        max_choir_length = max(max_choir_length, inc[i] + dec[i] - 1)

    return n - max_choir_length

def min_groups(w, n, prices):
    def can_form_group(max_price):
        count = 0
        i, j = 0, n - 1
        while i <= j:
            if prices[i] + prices[j] <= max_price:
                i += 1
            count += 1
            j -= 1
        return count

    if n == 0:
        return 0
    prices.sort()
    low, high = prices[0], sum(prices)
    while low < high:
        mid = (low + high) // 2
        if can_form_group(mid) <= n:
            high = mid
        else:
            low = mid + 1
    return low

def hanoi_double_iterative(n: int) -> int:
    if n <= 0:
        return 0
    moves = 0
    for i in range(1, n + 1):
        moves += 2 ** i - 1
    return moves * 2 - 2
